<script lang="ts">
 import { SlidersHorizontal, X, Search } from 'lucide-svelte'; import { products, categories, money, colorHex } from '../lib/data/products'; import { route, navigate } from '../lib/stores/router'; import ProductCard from '../lib/components/ProductCard.svelte';
 const params = $derived(new URLSearchParams($route.split('?')[1] || '')); let search = $state(''); let category = $state(''); let color = $state(''); let size = $state(''); let maxPrice = $state(5000); let sort = $state('featured'); let saleOnly = $state(false); let filtersOpen = $state(false);
 $effect(() => { search = params.get('q') || ''; category = params.get('category') || ''; saleOnly = params.get('edit') === 'sale'; });
 let filtered = $derived.by(() => { let list = products.filter(p => (!category || p.category === category) && (!color || p.color === color) && (!size || p.sizes.includes(size)) && p.price <= maxPrice && (!saleOnly || !!p.originalPrice) && (params.get('edit') !== 'new' || p.badge === 'New') && `${p.name} ${p.category} ${p.color} ${p.fabric}`.toLowerCase().includes(search.toLowerCase().trim())); if(sort === 'low') list.sort((a,b)=>a.price-b.price); if(sort==='high') list.sort((a,b)=>b.price-a.price); if(sort==='name') list.sort((a,b)=>a.name.localeCompare(b.name)); return list; });
 function reset() { search='';category='';color='';size='';maxPrice=5000;saleOnly=false;sort='featured'; if(params.get('edit')) navigate('/shop'); }
</script>
<div class="page-heading"><div class="breadcrumbs"><a href="#/">Home</a><span>/</span><span>The collection</span></div><span class="eyebrow">YOUR STORY, YOUR SILHOUETTE</span><h1>{params.get('edit') === 'new' ? 'Fresh chapters.' : params.get('edit') === 'sale' ? 'The offers edit.' : category || 'The collection.'}</h1><p>Thoughtful pieces for wherever your day takes you.</p></div>
<section class="shop-layout"><button class="button outline filter-toggle" onclick={() => filtersOpen = !filtersOpen}><SlidersHorizontal size={16}/> Filters</button><aside class:filters-visible={filtersOpen} class="filters"><div class="filter-title"><h3>Refine your edit</h3><button onclick={reset}>Reset</button></div><label class="filter-search"><Search size={15}/><input aria-label="Search collection" placeholder="Search pieces…" bind:value={search}/></label><fieldset><legend>Collection</legend><label class="radio-label"><input type="radio" bind:group={category} value=""/>All pieces</label>{#each categories as cat}<label class="radio-label"><input type="radio" bind:group={category} value={cat}/>{cat}</label>{/each}</fieldset><fieldset><legend>Colour</legend><div class="color-filters">{#each Object.entries(colorHex) as [label,hex]}<button class:selected={color===label} style={`--swatch:${hex}`} aria-label={`Filter ${label}`} aria-pressed={color===label} onclick={()=>color=color===label?'':label}><span></span>{label}</button>{/each}</div></fieldset><fieldset><legend>Size</legend><div class="size-filters">{#each ['XS','S','M','L','XL','XXL'] as s}<button class:selected={size===s} onclick={()=>size=size===s?'':s}>{s}</button>{/each}</div></fieldset><fieldset><legend>Price up to {money(maxPrice)}</legend><input type="range" min="1500" max="5000" step="100" bind:value={maxPrice} aria-label="Maximum price"/><div class="range-labels"><span>₹1,500</span><span>₹5,000</span></div></fieldset><label class="radio-label"><input type="checkbox" bind:checked={saleOnly}/>On offer only</label><button class="button dark mobile-apply" onclick={()=>filtersOpen=false}>Show {filtered.length} pieces</button></aside><div class="shop-results"><div class="results-toolbar"><span>{filtered.length} {filtered.length===1?'piece':'pieces'} in your edit</span><label>Sort by <select bind:value={sort} aria-label="Sort products"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="name">Name: A–Z</option></select></label></div>{#if search || color || size || category || saleOnly}<div class="filter-chips">{#if search}<button onclick={()=>search=''}>“{search}” <X size={12}/></button>{/if}{#if category}<button onclick={()=>category=''}>{category}<X size={12}/></button>{/if}{#if color}<button onclick={()=>color=''}>{color}<X size={12}/></button>{/if}{#if size}<button onclick={()=>size=''}>Size {size}<X size={12}/></button>{/if}{#if saleOnly}<button onclick={()=>saleOnly=false}>On offer<X size={12}/></button>{/if}</div>{/if}<div class="product-grid shop-products">{#each filtered as product}<ProductCard {product}/>{/each}</div>{#if !filtered.length}<div class="empty-state"><Search size={36}/><h2>No pieces in this edit.</h2><p>Try a different colour, collection, or price range.</p><button class="button dark" onclick={reset}>Clear filters</button></div>{/if}</div></section>
